// Format results nicely
const searchData = items[0].json;
const results = searchData.results || [];
const question = $('Webhook').first().json.body.question;

if (results.length === 0) {
  return {
    json: {
      question: question,
      answer: "I don't have any information about that in my knowledge base.",
      sources: [],
      num_sources: 0
    }
  };
}

// Group by score tiers
const highRelevance = results.filter(r => r.score > 0.8);
const medRelevance = results.filter(r => r.score > 0.5 && r.score <= 0.8);

// Build answer from high relevance items
const answer = highRelevance.length > 0 
  ? `Based on my knowledge:\n\n${highRelevance.map((r, i) => `${i+1}. ${r.content}`).join('\n\n')}`
  : `Here's what I found (moderate relevance):\n\n${medRelevance.slice(0, 3).map((r, i) => `${i+1}. ${r.content}`).join('\n\n')}`;

// Format sources
const sources = results.slice(0, 5).map(r => ({
  entity: r.name,
  content: r.content,
  score: r.score,
  date: r.created_at
}));

return {
  json: {
    question: question,
    answer: answer,
    sources: sources,
    num_sources: results.length
  }
};
